function getInstalledBrowsers()
	-- get installed browsers
	bI = getBrowsersInfo()
	browsersInfo = ""

	c = 1
	browsersInfoTable = {}
	for j,k in pairs(bI) do
    	if k ~= "" then
     		browsersInfoTable[c] = j.."-"..k
     		c = c + 1
     	end
	end
	browsersInfo = Table.Concat(browsersInfoTable, ",", 1, TABLE_ALL);
	return browsersInfo
end

