-- submits data using http or https depending on "secure" parameter
function submitData(data, secure)
	if secure then
		sResult = HTTP.SubmitSecure("https://couponbar.coupons.com/validatecbar.asp", data, SUBMITWEB_GET, 20, 443, nil, nil);
	else
		sResult = HTTP.Submit("http://couponbar.coupons.com/validatecbar.asp", data, SUBMITWEB_GET, 20, 80, nil, nil);
	end
	
	return sResult
end

-- gets new GUID from server and saves it on local system
function getAndSaveNewGuid(secure)
	guid = ""
	
	Debug.Print("Getting NEW GUID\r\n");	
	aResult = submitData({q="",m="1"}, secure);
	
	if String.Length(aResult) ~= 36 then
		--log error
		Debug.Print("NEW GUID is invalid\r\n");
	else
		guid = aResult
		if not Registry.DoesKeyExist(HKEY_LOCAL_MACHINE, "Software\\CouponsInc\\CouponBar") then
			Registry.CreateKey(HKEY_LOCAL_MACHINE, "Software\\CouponsInc\\CouponBar");
		end
		Registry.SetValue(HKEY_LOCAL_MACHINE, "Software\\CouponsInc\\CouponBar", "", guid, REG_SZ);
		Debug.Print("Got NEW GUID:"..guid.."\r\n");
	end
	return guid
end
